package com.alan.thormonitor;
import android.content.*;import android.database.Cursor;import android.net.Uri;import android.provider.DocumentsContract;import android.os.*;
import java.io.*;import java.nio.file.Files;import java.util.*;import org.json.*;
/** Browser transfers use the same explicit storage grants, never shell privileges. */
final class WebFiles {
 static final class Conflict extends IllegalStateException{Conflict(String message){super(message);}}
 static final long MAX=64L*1024*1024*1024;
 private static Uri tree(Context c,String root){if(!Arrays.asList("internal","sd").contains(root))throw new IllegalArgumentException("Choose Internal or microSD");String value=FileAccess.folder(c,root);if(value.isEmpty())throw new IllegalStateException("Choose this folder in Thor Monitor first");return Uri.parse(value);}
 private static Uri child(Context c,Uri tree,Uri parent,String name)throws Exception{
  Uri children=DocumentsContract.buildChildDocumentsUriUsingTree(tree,DocumentsContract.getDocumentId(parent));try(Cursor cursor=c.getContentResolver().query(children,new String[]{"document_id","_display_name"},null,null,null)){if(cursor!=null)while(cursor.moveToNext())if(name.equals(cursor.getString(1)))return DocumentsContract.buildDocumentUriUsingTree(tree,cursor.getString(0));}return null;
 }
 private static Uri document(Context c,Uri tree,String path)throws Exception{Uri doc=DocumentsContract.buildDocumentUriUsingTree(tree,DocumentsContract.getTreeDocumentId(tree));for(String part:FileAccess.segments(path)){doc=child(c,tree,doc,part);if(doc==null)throw new FileNotFoundException("Folder or file is unavailable");}return doc;}
 static JSONObject roots(Context c)throws Exception{JSONArray rows=new JSONArray();for(String id:new String[]{"internal","sd"})if(SharedFiles.enabled(c)?SharedFiles.roots(c).containsKey(id):!FileAccess.folder(c,id).isEmpty())rows.put(new JSONObject().put("id",id).put("name",id.equals("sd")?"microSD":"Internal"));return new JSONObject().put("roots",rows);}
 private static File base(Context c,String id){File root=SharedFiles.roots(c).get(id);if(root==null)throw new IllegalArgumentException("Storage is unavailable");return root;}
 static JSONObject list(Context c,String root,String path,int offset)throws Exception{
  if(offset<0||offset>1000000)throw new IllegalArgumentException("Invalid page");JSONArray rows=new JSONArray();boolean more=false;
  if(SharedFiles.enabled(c)){File file=SharedFiles.resolve(base(c,root),path);File[] children=file.listFiles();if(children==null)throw new SecurityException("This folder is protected or unavailable");Arrays.sort(children,Comparator.comparing(f->f.getName().toLowerCase(Locale.ROOT)));int end=Math.min(children.length,offset+200);for(int n=offset;n<end;n++){File f=children[n];rows.put(new JSONObject().put("name",f.getName()).put("dir",f.isDirectory()).put("size",f.isDirectory()?JSONObject.NULL:f.length()));}more=end<children.length;
  }else{Uri tree=tree(c,root),doc=document(c,tree,path),children=DocumentsContract.buildChildDocumentsUriUsingTree(tree,DocumentsContract.getDocumentId(doc));int i=0;try(Cursor cursor=c.getContentResolver().query(children,new String[]{"_display_name","mime_type","_size"},null,null,null)){if(cursor==null)throw new IOException("Folder unavailable");while(cursor.moveToNext()){if(i++<offset)continue;if(rows.length()==200){more=true;break;}String name=cursor.getString(0);FileAccess.validateName(name);rows.put(new JSONObject().put("name",name).put("dir",DocumentsContract.Document.MIME_TYPE_DIR.equals(cursor.getString(1))).put("size",cursor.isNull(2)?JSONObject.NULL:cursor.getLong(2)));}}}
  return new JSONObject().put("entries",rows).put("next",more?offset+rows.length():-1);
 }
 static final class Download implements Closeable {final InputStream stream;final long length,modified;Download(InputStream in,long n){this(in,n,0);}Download(InputStream in,long n,long m){stream=in;length=n;modified=m;}String etag(){return "\""+Long.toHexString(length)+"-"+Long.toHexString(modified)+"\"";}public void close()throws IOException{stream.close();}}
 static Download open(Context c,String root,String path)throws Exception{
  if(SharedFiles.enabled(c)){File file=SharedFiles.resolve(base(c,root),path);if(!file.isFile()||file.length()>MAX)throw new FileNotFoundException("File unavailable or too large");return new Download(new FileInputStream(file),file.length(),file.lastModified());}
  Uri doc=document(c,tree(c,root),path);long size=-1;try(Cursor cursor=c.getContentResolver().query(doc,new String[]{"_size","mime_type"},null,null,null)){if(cursor!=null&&cursor.moveToFirst()&&!DocumentsContract.Document.MIME_TYPE_DIR.equals(cursor.getString(1))&&!cursor.isNull(0))size=cursor.getLong(0);}if(size<0||size>MAX)throw new IOException("File size unavailable or exceeds 64 GiB");InputStream stream=c.getContentResolver().openInputStream(doc);if(stream==null)throw new FileNotFoundException();return new Download(stream,size);
 }
 interface Guard {void check()throws IOException;}
 static void copy(InputStream in,OutputStream out,long length,Guard guard)throws IOException{byte[] buffer=new byte[65536];long until=SystemClock.elapsedRealtime()+20*60000L;while(length>0){guard.check();if(SystemClock.elapsedRealtime()>until)throw new IOException("Transfer time limit reached");int n=in.read(buffer,0,(int)Math.min(buffer.length,length));if(n<0)throw new EOFException("Incomplete file");guard.check();out.write(buffer,0,n);length-=n;}guard.check();}
 static void upload(Context c,String root,String path,String name,long size,InputStream in,Guard guard)throws Exception{
  FileAccess.validateName(name);if(size<0||size>MAX)throw new IllegalArgumentException("File exceeds 64 GiB");
  if(SharedFiles.enabled(c)){File folder=SharedFiles.resolve(base(c,root),path);if(!folder.isDirectory())throw new FileNotFoundException("Folder unavailable");File target=SharedFiles.resolve(base(c,root),path.isEmpty()?name:path+"/"+name);if(target.exists())throw new Conflict("A file with this name already exists");File temp=File.createTempFile(".thor-web-",".part",folder);try{try(FileOutputStream out=new FileOutputStream(temp)){copy(in,out,size,guard);out.getFD().sync();}Files.move(temp.toPath(),target.toPath());}finally{temp.delete();}return;}
  ContentResolver resolver=c.getContentResolver();Uri tree=tree(c,root),folder=document(c,tree,path);if(child(c,tree,folder,name)!=null)throw new Conflict("A file with this name already exists");Uri partial=DocumentsContract.createDocument(resolver,folder,"application/octet-stream",".thor-web-"+UUID.randomUUID());if(partial==null)throw new IOException("Folder is not writable");boolean done=false;
  try{try(OutputStream out=resolver.openOutputStream(partial,"w")){if(out==null)throw new IOException();copy(in,out,size,guard);out.flush();}if(child(c,tree,folder,name)!=null)throw new Conflict("A file with this name appeared during upload");if(DocumentsContract.renameDocument(resolver,partial,name)==null)throw new IOException("Could not finish upload");done=true;}finally{if(!done)try{DocumentsContract.deleteDocument(resolver,partial);}catch(Exception ignored){}}
 }
}
